-- Fixed synthetic sales order. Runs inside the rollback-only isolated transaction.
INSERT INTO T201_sale_order_master ([sys_no],[sale_type],[sale_order_no],[edit_date],[input_date],[customer_order_no],[customer_no],[mid_trader_no],[invoice_receiver_no],[produce_stage],[money_no],[exchange_rate],[sale_price_type],[sale_tax_rate],[pay_no],[account_days],[more_rate],[less_rate],[worker_no],[station_guid],[dept_no],[vise_tag],[audit_tag],[state_type],[edit_user_no],[order_note],[user_field1],[user_field2],[user_field3],[user_field4],[user_field5],[row_ver_guid],[order_type],[reaudit_tag],[allow_tag],[roll_plan_tag],[need_audit_level],[price_audit_level],[source_type],[final_customer_no],[produce_order_no],[audit_date],[audit_worker_no],[transfer_tag],[customer_property],[order_invoice_no],[sample_effect])
SELECT TOP 1 t.[sys_no],t.[sale_type],@UrgentOrder,@UrgentInput,@UrgentInput,@UrgentOrder,t.[customer_no],t.[mid_trader_no],t.[invoice_receiver_no],t.[produce_stage],t.[money_no],t.[exchange_rate],t.[sale_price_type],t.[sale_tax_rate],t.[pay_no],t.[account_days],t.[more_rate],t.[less_rate],t.[worker_no],t.[station_guid],t.[dept_no],t.[vise_tag],'T','run',t.[edit_user_no],t.[order_note],t.[user_field1],t.[user_field2],t.[user_field3],t.[user_field4],t.[user_field5],t.[row_ver_guid],t.[order_type],'F',t.[allow_tag],t.[roll_plan_tag],t.[need_audit_level],t.[price_audit_level],t.[source_type],t.[final_customer_no],t.[produce_order_no],t.[audit_date],t.[audit_worker_no],t.[transfer_tag],t.[customer_property],t.[order_invoice_no],t.[sample_effect]
